class Solution {
    private int[] a, buf;

    public long minAdjacentSwaps(int[] heights) {
        a = heights.clone();
        buf = new int[a.length];
        return sort(0, a.length);
    }

    private long sort(int lo, int hi) {
        if (hi - lo <= 1) return 0;
        int mid = (lo + hi) >>> 1;
        long count = sort(lo, mid) + sort(mid, hi);
        int i = lo, j = mid, k = lo;
        while (i < mid && j < hi) {
            if (a[i] <= a[j]) buf[k++] = a[i++];
            else { buf[k++] = a[j++]; count += mid - i; }
        }
        while (i < mid) buf[k++] = a[i++];
        while (j < hi) buf[k++] = a[j++];
        System.arraycopy(buf, lo, a, lo, hi - lo);
        return count;
    }
}

