static long long count_sort(int* a, int* buf, int lo, int hi) {
    if (hi - lo <= 1) return 0;
    int mid = lo + (hi - lo) / 2;
    long long count = count_sort(a, buf, lo, mid) + count_sort(a, buf, mid, hi);
    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi) {
        if (a[i] <= a[j]) buf[k++] = a[i++];
        else { buf[k++] = a[j++]; count += mid - i; }
    }
    while (i < mid) buf[k++] = a[i++];
    while (j < hi) buf[k++] = a[j++];
    memcpy(a + lo, buf + lo, (hi - lo) * sizeof(int));
    return count;
}

long long minAdjacentSwaps(int* heights, int heightsSize) {
    int* a = malloc(heightsSize * sizeof(int));
    int* buf = malloc(heightsSize * sizeof(int));
    memcpy(a, heights, heightsSize * sizeof(int));
    long long count = count_sort(a, buf, 0, heightsSize);
    free(a); free(buf);
    return count;
}
